class Solution {
    public int longestSubsequence(int[] arr, int difference) {
        int n = arr.length;
        int maxLen = 1;
        for (int i = 0; i < n; i++) {
            int len = 1;
            int cur = arr[i];
            for (int j = i + 1; j < n; j++) {
                if (arr[j] - cur == difference) {
                    len++;
                    cur = arr[j];
                }
            }
            maxLen = Math.max(maxLen, len);
        }
        return maxLen;
    }
}

